class IntervalNode:
    def __init__(self, start: int, end: int, res_id: str):
        self.start = start
        self.end = end
        self.res_id = res_id
        self.max_end = end
        self.left = None
        self.right = None

def find_conflicting_reservations(reservations: list[tuple[int, int, str]], query_start: int, query_end: int) -> list[str]:
    """Uses interval tree subtree max_end bounds to find all reservations overlapping a target window [start, end)."""
    if query_start >= query_end or not reservations:
        return []

    root = None

    def insert(node, start, end, res_id):
        if node is None:
            return IntervalNode(start, end, res_id)
        if start < node.start:
            node.left = insert(node.left, start, end, res_id)
        else:
            node.right = insert(node.right, start, end, res_id)
        best = node.end
        if node.left and node.left.max_end > best:
            best = node.left.max_end
        if node.right and node.right.max_end > best:
            best = node.right.max_end
        node.max_end = best
        return node

    for s, e, rid in reservations:
        root = insert(root, s, e, rid)

    conflicts = []

    def collect_overlaps(node):
        if node is None:
            return
        if node.left and node.left.max_end > query_start:
            collect_overlaps(node.left)
        if node.start < query_end and query_start < node.end:
            conflicts.append(node.res_id)
        if node.right and node.start < query_end and node.right.max_end > query_start:
            collect_overlaps(node.right)

    collect_overlaps(root)
    return conflicts
